// pnpm --filter @lf/ui build:tokens
// docs/design/tokens.json (Figma variables) → src/tokens/tokens.css (CSS variables for the 4 themes
// × light/dark, plus "system", which follows the device) and src/tokens/tokens.ts (the same values
// for the admin's custom-palette preview). The accessibility additions from docs/design/README.md
// are applied here. Generated files: do not edit by hand.
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '../../..');
type Tokens = {
  color: { modes: string[]; tokens: Record<string, Record<string, string>> };
  size: Record<string, number>;
  effects: Record<
    string,
    {
      type: string;
      x?: number;
      y?: number;
      blur?: number;
      spread?: number;
      color?: string;
      radius?: number;
    }[]
  >;
};
const tokens = JSON.parse(
  readFileSync(path.join(root, 'docs/design/tokens.json'), 'utf8'),
) as Tokens;

const THEMES = ['navy', 'forest', 'indigo', 'teal'] as const;
const MODES = ['light', 'dark'] as const;

/** WCAG fixes to Figma values (docs/design/README.md). */
const BORDER_CONTROL: Record<string, string> = {
  'navy-light': '#838791',
  'navy-dark': '#64718a',
  'forest-light': '#838877',
  'forest-dark': '#677669',
  'indigo-light': '#87859f',
  'indigo-dark': '#6a6889',
  'teal-light': '#7a8b8c',
  'teal-dark': '#5d7877',
};

function palette(mode: string): Record<string, string> {
  const p: Record<string, string> = {};
  for (const [name, values] of Object.entries(tokens.color.tokens)) {
    const v = values[mode];
    if (!v) throw new Error(`${name} has no value for ${mode}`);
    p[name] = v;
  }
  const dark = mode.endsWith('-dark');
  p['border/control'] = BORDER_CONTROL[mode] ?? p['border/line'] ?? '';
  p['status/on-danger'] = dark ? (p['bg/canvas'] ?? '') : '#ffffff';
  p['status/on-success'] = dark ? (p['bg/canvas'] ?? '') : '#ffffff';
  return p;
}

const cssName = (token: string) => `--lf-${token.replace('/', '-')}`;
const block = (
  selector: string,
  p: Record<string, string>,
  scheme: 'light' | 'dark',
  indent = '',
) =>
  `${indent}${selector} {\n${indent}  color-scheme: ${scheme};\n${Object.entries(p)
    .map(([k, v]) => `${indent}  ${cssName(k)}: ${v};`)
    .join('\n')}\n${indent}}\n`;

let css =
  '/* Generated by packages/ui/scripts/build-tokens.ts from docs/design/tokens.json. Do not edit. */\n\n';
// Before the tenant's theme loads: the NSU default (Teal · Dark).
css += block(':root', palette('teal-dark'), 'dark');
for (const theme of THEMES) {
  const light = palette(`${theme}-light`);
  const dark = palette(`${theme}-dark`);
  css += `\n/* ${theme} */\n`;
  css += block(
    `[data-theme='${theme}'][data-mode='light'],\n[data-theme='${theme}'][data-mode='system']`,
    light,
    'light',
  );
  css += block(`[data-theme='${theme}'][data-mode='dark']`, dark, 'dark');
  css += `@media (prefers-color-scheme: dark) {\n${block(`  [data-theme='${theme}'][data-mode='system']`, dark, 'dark', '')}}\n`;
}

const shadow = (name: string) =>
  (tokens.effects[name] ?? [])
    .filter((e) => e.type === 'drop')
    .map(
      (e) =>
        `${e.x ?? 0}px ${e.y ?? 0}px ${e.blur ?? 0}px ${e.spread ?? 0}px ${e.color ?? '#0000'}`,
    )
    .join(', ');
css += `\n:root {\n  --lf-shadow-card: ${shadow('Shadow/Card')};\n  --lf-shadow-hover: ${shadow('Shadow/Hover')};\n  --lf-shadow-pop: ${shadow('Shadow/Pop')};\n}\n`;

const outDir = path.join(root, 'packages/ui/src/tokens');
writeFileSync(path.join(outDir, 'tokens.css'), css);

const presets = Object.fromEntries(
  THEMES.map((t) => [t, Object.fromEntries(MODES.map((m) => [m, palette(`${t}-${m}`)]))]),
);
writeFileSync(
  path.join(outDir, 'tokens.ts'),
  `// Generated by packages/ui/scripts/build-tokens.ts from docs/design/tokens.json. Do not edit.\n` +
    `export const THEME_PALETTES = ${JSON.stringify(presets, null, 2)} as const;\n\n` +
    `export type ThemeName = keyof typeof THEME_PALETTES;\n` +
    `export type ColourToken = keyof (typeof THEME_PALETTES)['teal']['light'];\n` +
    `export const cssVar = (token: ColourToken): string => \`--lf-\${token.replace('/', '-')}\`;\n`,
);
process.stdout.write(
  `Wrote ${THEMES.length * MODES.length} colour modes to packages/ui/src/tokens.\n`,
);
